                        facequads[face_array_index].vertex_2 =
                            (face_row + 1) * ((unsigned short)width_cells + 1) + face_column + 1;
                        facequads[face_array_index].vertex_3 =
                            face_column + (face_row + 1) * ((unsigned short)width_cells + 1);
