p=Path('tools/match/scratches/initialize_loopout_path_template_pair');out=Path('/tmp/snail-goal-loopout-residual-owners');out.mkdir(exist_ok=True);cfg=m.load_scratch_config(p);base=(p/'scratch.cpp').read_text();(out/'baseline.cpp').write_text(base);forms={'baseline':base}
def radius(s):return s.replace('    float loop_radius = curve_count_f * 0.15915494f;','    curve_source = curve_count_f * 0.15915494f;',1).replace('loop_radius','curve_source')
def shared_float(s,departure=False):
 s=s.replace('    int i;','    int i;\n    float sample_f;',1).replace('        float z = (float)i;','        sample_f = (float)i;',1)
 a=s.index('    for (i = 0;');b=s.index('\n    }',a);s=s[:a]+s[a:b].replace('z_taper = z *','z_taper = sample_f *').replace('position.z = z;','position.z = sample_f;')+s[b:]
 s=s.replace('            float sample_f = (float)i;','            sample_f = (float)i;',1)
 if departure:
  a=s.index('    int departure_start');b=s.index('    Vector3 circle_center',a);part=s[a:b].replace('        int sample_index = departure_start + i;','        int sample_index = departure_start + i;\n        sample_f = (float)i;',1).replace('(1.0f - (float)i *','(1.0f - sample_f *');s=s[:a]+part+s[b:]
 return s
def sample_owner(s,kind):
 a=s.index('            primary_samples[sample_index].center_x =');b=s.index('            primary_samples[sample_index].center_x +=',a);part=s[a:b]
 if kind=='pointer-spelling':part=part.replace('primary_samples[sample_index].','(primary_samples + sample_index)->').replace('primary_samples[departure_start].','(primary_samples + departure_start)->')
 elif kind=='bank-pointer':part='            PathAttachmentSample *curve_samples = primary_samples;\n'+part.replace('primary_samples','curve_samples')
 elif kind=='center-reference':part='            float &center_x = primary_samples[sample_index].center_x;\n'+part.replace('primary_samples[sample_index].center_x =','center_x =',1)
 elif kind=='endpoint-values':part='            float entry_center = primary_samples[0].center_x;\n            float exit_center = primary_samples[departure_start].center_x;\n'+part.replace('primary_samples[0].center_x','entry_center').replace('primary_samples[departure_start].center_x','exit_center')
 elif kind=='delta-value':
  expr='(primary_samples[departure_start].center_x -\n                 primary_samples[0].center_x)';assert expr in part;part='            float center_delta = primary_samples[departure_start].center_x -\n                primary_samples[0].center_x;\n'+part.replace(expr,'center_delta')
 return s[:a]+part+s[b:]
def radial(s):
 for side in ['primary','secondary']:
  old=f'''            {side}_samples[sample_index].transform.basis_up.x = 0.0f;
            {side}_samples[sample_index].transform.basis_up.y =
                -(circle_center.y - {side}_samples[sample_index].transform.position.y);
            {side}_samples[sample_index].transform.basis_up.z =
                -(circle_center.z - {side}_samples[sample_index].transform.position.z);'''
  assert old in s
  new=f'''            {side}_samples[sample_index].transform.basis_up = Vector3(
                0.0f,
                -(circle_center.y - {side}_samples[sample_index].transform.position.y),
                -(circle_center.z - {side}_samples[sample_index].transform.position.z));''';s=s.replace(old,new,1)
 return s
for parent,src in [('local-radius',base),('parameter-radius',radius(base))]:
 forms[parent+'-shared-float']=shared_float(src)
 forms[parent+'-shared-float-departure']=shared_float(src,True)
 forms[parent+'-radial-vectors']=radial(src)
 for kind in ['pointer-spelling','bank-pointer','center-reference','endpoint-values','delta-value']:forms[parent+'-'+kind]=sample_owner(src,kind)
 # A mesh-local width snapshot expresses the loop bound/conversion owner.
 for owner in ['local','parameter']:
  s=src;a=s.index('    for (mesh_row');b=s.index('    for (face_row',a);part=s[a:b];name='row_width' if owner=='local' else 'width_cells_';decl='int row_width' if owner=='local' else name
  old='''        for (mesh_column = 0; mesh_column <= width_cells; ++mesh_column)''';assert old in part
  part=part.replace(old,f'        {decl} = width_cells;\n        for (mesh_column = 0; mesh_column <= {name}; ++mesh_column)',1).replace('(float)width_cells * 0.5f',f'(float){name} * 0.5f')
  forms[parent+'-'+owner+'-mesh-width']=s[:a]+part+s[b:]
