 base=(out/(parent+'.cpp')).read_text()
 a=base.index('            PathAttachmentSample *curve_samples');b=base.index('            primary_samples[sample_index].center_x +=',a);part=base[a:b]
 for style in ['exit-pointer','exit-reference','entry-arrow','both-pointers','const-bank','scoped-bank']:
  new=part
  if style in ['exit-pointer','both-pointers']:
   new=new.replace('            curve_samples[sample_index].center_x =','            PathAttachmentSample *exit_sample = curve_samples + departure_start;\n            curve_samples[sample_index].center_x =',1).replace('curve_samples[departure_start].center_x','exit_sample->center_x')
  if style=='both-pointers':new=new.replace('            curve_samples[sample_index].center_x =','            PathAttachmentSample *current_sample = curve_samples + sample_index;\n            current_sample->center_x =',1)
  if style=='exit-reference':new=new.replace('            curve_samples[sample_index].center_x =','            const PathAttachmentSample &exit_sample = curve_samples[departure_start];\n            curve_samples[sample_index].center_x =',1).replace('(curve_samples[departure_start].center_x -','(exit_sample.center_x -')
