  forms[parent+'-'+style]=base[:a]+new+base[b:]
 # Natural divisions retained by the mobile source, with all combinations.
 sites=[('lead-divide',lambda s:s.replace('z * 0.11111111f','z / 9.0f')),('departure-divide',lambda s:s.replace('(float)i * 0.33333334f','(float)i / 3.0f')),('radius-divide',lambda s:s.replace('curve_count_f * 0.15915494f','curve_count_f / 6.2831855f'))]
