 if results:
  r=results[0];(out/(label+'.diff')).write_text('\n'.join(difflib.unified_diff(r.target_lines,r.candidate_lines,n=3)));(out/(label+'-code.json')).write_text(json.dumps({'target':[{'offset':i.offset,'text':i.text} for i in r.target_disassembly],'candidate':[{'offset':i.offset,'text':i.text} for i in r.candidate_disassembly],'audit':m._masked_audit_cache_payload(r.masked_operand_audit),'frame':m.stack_frame_diagnostic_payload(r)},indent=2))
